-- 개원 안내 공지 (대표 고정)
INSERT OR IGNORE INTO notices (id, title, content, pinned) VALUES
(1, '고수치과의원 2026년 11월 2일 개원 예정 안내', '안녕하세요, 고수치과의원입니다.

고수치과의원이 2026년 11월 2일, 내포신도시(충청남도 예산군 삽교읍 예학로 93, 5층)에 개원할 예정입니다.

"신뢰를 바탕으로 옳은 진료를 고수하며, 한 사람의 삶을 더 나은 방향으로 바꿉니다."라는 미션 아래, 조원익 대표원장을 비롯한 의료진이 정성껏 준비하고 있습니다.

개원 전 상담 예약은 홈페이지 예약 페이지를 통해 남겨주시면, 준비가 완료되는 대로 순차적으로 연락드리겠습니다.

감사합니다.', 1);

-- 샘플 원장 칼럼 (개원 준비 인사)
INSERT OR IGNORE INTO posts (id, slug, title, content, author_slug, meta_description, category) VALUES
(1, 'greeting-open-2026', '내포신도시에 고수치과의원을 준비하며 — 개원 인사', '<h2>안녕하세요, 고수치과의원 대표원장 조원익입니다.</h2><p>2026년 11월, 내포신도시에 고수치과의원의 문을 엽니다. 이름에 담긴 뜻 그대로, 유행을 좇기보다 <strong>옳은 진료를 고수(固守)</strong>하는 치과가 되고자 합니다.</p><h2>왜 &#39;고수&#39;인가</h2><p>치과 치료는 한 번 하면 되돌리기 어렵습니다. 그래서 저희는 세 가지 원칙을 지키려 합니다.</p><ul><li><strong>정확한 진단</strong> — 파노라마·CT 기반의 정밀 진단으로 필요한 치료만 제안합니다.</li><li><strong>충분한 설명</strong> — 치료 방법, 기간, 비용, 그리고 부작용 가능성까지 이해되실 때까지 설명드립니다.</li><li><strong>결과에 대한 책임</strong> — 치료 후 정기 검진과 유지 관리까지 함께합니다.</li></ul><h2>내포신도시 주민 여러분께</h2><p>주키즈소아청소년과 건물 5층, 중흥S클래스더시티 앞에서 만나 뵙겠습니다. 개원 전에도 홈페이지를 통해 상담 예약을 남겨주시면 순차적으로 연락드리겠습니다.</p><p>치과 치료의 두려움을 신뢰로 바꾸는 치과, 고수치과의원이 되겠습니다.</p><p><em>※ 치료 결과는 개인에 따라 다를 수 있으며, 모든 시술은 충분한 상담 후 진행됩니다.</em></p>', 'cho-wonik', '2026년 11월 내포신도시에 개원하는 고수치과의원 조원익 대표원장의 개원 인사말. 정확한 진단, 충분한 설명, 결과에 대한 책임이라는 세 가지 진료 원칙을 소개합니다.', NULL),
(2, 'implant-checklist-before', '임플란트 치료 전 반드시 확인해야 할 5가지', '<h2>임플란트, 시작 전 점검이 절반입니다</h2><p>임플란트는 상실된 치아를 대체하는 대표적인 치료지만, 시작 전 확인해야 할 것들이 있습니다. 고수치과의원이 정리한 다섯 가지 체크리스트입니다.</p><h3>1. 잇몸뼈(치조골) 상태</h3><p>임플란트는 뼈에 식립하는 치료입니다. CT 촬영으로 뼈의 양과 밀도를 확인하고, 부족한 경우 뼈이식 여부를 먼저 계획해야 합니다.</p><h3>2. 전신 질환 여부</h3><p>당뇨, 골다공증, 심혈관 질환이 있거나 항응고제를 복용 중이라면 반드시 의료진에게 알려주세요. 치료 계획과 시기가 달라질 수 있습니다.</p><h3>3. 잇몸 건강</h3><p>치주염이 있는 상태에서 임플란트를 심으면 임플란트 주위염으로 이어질 수 있습니다. 잇몸 치료가 선행되어야 하는 경우가 많습니다.</p><h3>4. 수면·흡연 습관</h3><p>흡연은 임플란트 성공률에 영향을 주는 대표적 요인입니다. 최소한 수술 전후 기간의 금연이 권장됩니다.</p><h3>5. 유지 관리 계획</h3><p>임플란트는 심는 것보다 오래 쓰는 것이 중요합니다. 정기 검진 주기를 의료진과 미리 정해두세요.</p><p><em>※ 임플란트 시술은 출혈, 감염, 신경 손상 등의 부작용이 발생할 수 있으며, 치료 결과는 개인의 구강 상태에 따라 다를 수 있습니다. 시술 전 의료진과 충분히 상담하시기 바랍니다.</em></p>', 'cho-wonik', '임플란트 치료 전 확인해야 할 잇몸뼈 상태, 전신 질환, 잇몸 건강, 생활 습관, 유지 관리 계획 5가지를 고수치과의원이 정리했습니다.', '임플란트');
